function trimmed(text) {
  const t = text.trim()
  if (!t) throw new Error('empty message')
  if (t.length > 4000) throw new Error('message too long')
  return t
}

export function sendMessage(channel, text) {
  if (!canPost(channel)) throw new Error('forbidden')
  const message = save(channel, trimmed(text))
  for (const user of parseMentions(text)) push(user, message)
  return message
}

export function editMessage(message, text) {
  if (message.author !== currentUser()) throw new Error('forbidden')
  return save(message.channel, trimmed(text), message.id)
}

