// Who mentioned whom, kept so a notification can say it.
export interface Mention {
  messageId: string
  from: string
  to: string
}

const mentions: Mention[] = []

export function remember(m: Mention) {
  mentions.push(m)
}

export function mentionedBy(messageId: string, to: string) {
  return mentions.find(m => m.messageId === messageId && m.to === to)?.from
}

// The line under a notification: who mentioned you.
export function MentionedBy({ name }: { name: string }) {
  return <span className="mentioned-by">@{name}</span>
}

