// Finding messages that contain a word.
import { indexMessage } from './index'

export function search(messages, word) {
  return messages.filter(m => indexMessage(m).includes(word.toLowerCase()))
}

export function highlight(text, word) {
  if (!word) return text
  const at = text.toLowerCase().indexOf(word.toLowerCase())
  if (at < 0) return text
  return text.slice(0, at) + '<mark>' + text.slice(at, at + word.length) + '</mark>' + text.slice(at + word.length)
}

