// Users: sign-in and the profile behind it.
import { db } from '../../db/schema'
import { limiter } from '../limits'

const signIns = limiter({ per: 'ip', max: 10, window: 60_000 })

export async function signIn(req) {
  if (!signIns.take(req.ip)) return { status: 429 }
  const user = await db.users.byEmail(req.body.email)
  if (!user || !(await user.checkPassword(req.body.password))) {
    return { status: 401 }
  }
  return { status: 200, session: await db.sessions.open(user.id) }
}

export async function profile(req) {
  return { status: 200, user: await db.users.byId(req.session.userId) }
}

